//! Bridge types. Serialized camelCase; TS is generated by ts-rs on `cargo test`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::vmr::VmType;
use crate::vmr::layout::{self, BUSES, STRIPS};
use crate::vmr::params::BusMode as VmrBusMode;

/// Voicemeeter edition as reported by `GetVoicemeeterType`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub enum VmEdition {
    Basic,
    Banana,
    Potato,
}

impl From<VmType> for VmEdition {
    fn from(t: VmType) -> Self {
        match t {
            VmType::Basic => VmEdition::Basic,
            VmType::Banana => VmEdition::Banana,
            VmType::Potato => VmEdition::Potato,
        }
    }
}

/// Connection state machine. `status` is the discriminant.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "status", rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub enum ConnectionState {
    /// The engine hasn't looked yet (first few ms after start).
    Starting,
    /// `VoicemeeterRemote64.dll` wasn't found. `searched` lists every path tried.
    DllNotFound { searched: Vec<String> },
    /// The DLL exists but couldn't be loaded (missing export, wrong architecture, …).
    DllError { message: String },
    /// `VBVMR_Login` returned an error. Not retryable without restarting Mixdeck.
    LoginFailed { code: i32, message: String },
    /// Logged in, but Voicemeeter isn't running. The engine polls about once a second.
    NotRunning,
    /// Voicemeeter is running but isn't Potato.
    WrongEdition {
        #[serde(rename = "vmType")]
        #[ts(rename = "vmType")]
        vm_type: VmEdition,
    },
    Connected {
        #[serde(rename = "vmType")]
        #[ts(rename = "vmType")]
        vm_type: VmEdition,
        /// Voicemeeter version, e.g. "3.1.3.0".
        version: String,
    },
}

impl ConnectionState {
    pub fn is_connected(&self) -> bool {
        matches!(self, ConnectionState::Connected { .. })
    }
}

