#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub struct Strip {
    pub index: u8,
    pub kind: StripKind,
    /// User label; empty means "use the default name" (`STRIP_DEFAULT_NAMES`).
    pub label: String,
    /// dB, -60..+12.
    pub gain: f32,
    pub mute: bool,
    pub solo: bool,
    /// Hardware strips only (false on virtual strips).
    pub mono: bool,
    /// Virtual strips only (false on hardware strips).
    pub mc: bool,
    /// A1..A5, B1..B3.
    pub routes: [bool; 8],
    /// Current device name (hardware strips only; `None` when unselected).
    pub device: Option<String>,
    pub quick: StripQuick,
}

/// Bus mode (`Bus[j].mode.*`). Read: the flag that is 1. Write: set `mode.<x>` to 1.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub enum BusMode {
    #[default]
    Normal,
    Amix,
    Bmix,
    Repeat,
    Composite,
    TvMix,
    UpMix21,
    UpMix41,
    UpMix61,
    CenterOnly,
    LfeOnly,
    RearOnly,
}

impl BusMode {
    pub const fn to_vmr(self) -> VmrBusMode {
        match self {
            BusMode::Normal => VmrBusMode::Normal,
            BusMode::Amix => VmrBusMode::Amix,
            BusMode::Bmix => VmrBusMode::Bmix,
            BusMode::Repeat => VmrBusMode::Repeat,
            BusMode::Composite => VmrBusMode::Composite,
            BusMode::TvMix => VmrBusMode::TvMix,
            BusMode::UpMix21 => VmrBusMode::UpMix21,
            BusMode::UpMix41 => VmrBusMode::UpMix41,
            BusMode::UpMix61 => VmrBusMode::UpMix61,
            BusMode::CenterOnly => VmrBusMode::CenterOnly,
            BusMode::LfeOnly => VmrBusMode::LfeOnly,
            BusMode::RearOnly => VmrBusMode::RearOnly,
        }
    }

    pub const fn from_vmr(m: VmrBusMode) -> Self {
        match m {
            VmrBusMode::Normal => BusMode::Normal,
            VmrBusMode::Amix => BusMode::Amix,
            VmrBusMode::Bmix => BusMode::Bmix,
            VmrBusMode::Repeat => BusMode::Repeat,
            VmrBusMode::Composite => BusMode::Composite,
            VmrBusMode::TvMix => BusMode::TvMix,
            VmrBusMode::UpMix21 => BusMode::UpMix21,
            VmrBusMode::UpMix41 => BusMode::UpMix41,
            VmrBusMode::UpMix61 => BusMode::UpMix61,
            VmrBusMode::CenterOnly => BusMode::CenterOnly,
            VmrBusMode::LfeOnly => BusMode::LfeOnly,
            VmrBusMode::RearOnly => BusMode::RearOnly,
        }
    }
}

