/// The Mixer page: the `core` group. `rev` increases on every change; `rev == 0` means no
/// data has been read from Voicemeeter yet.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub struct MixerState {
    pub connection: ConnectionState,
    pub strips: Vec<Strip>,
    pub buses: Vec<Bus>,
    #[ts(type = "number")]
    pub rev: u64,
}

impl Default for MixerState {
    fn default() -> Self {
        Self {
            connection: ConnectionState::Starting,
            strips: (0..STRIPS).map(Strip::empty).collect(),
            buses: (0..BUSES).map(Bus::empty).collect(),
            rev: 0,
        }
    }
}

impl Strip {
    pub fn empty(i: usize) -> Self {
        let hw = layout::is_hardware_strip(i);
        Self {
            index: i as u8,
            kind: if hw {
                StripKind::Hardware
            } else {
                StripKind::Virtual
            },
            label: String::new(),
            gain: 0.0,
            mute: false,
            solo: false,
            mono: false,
            mc: false,
            routes: [false; 8],
            device: None,
            quick: if hw {
                StripQuick::Hardware(HardwareQuick::default())
            } else {
                StripQuick::Virtual(VirtualQuick::default())
            },
        }
    }
}

impl Bus {
    pub fn empty(j: usize) -> Self {
        Self {
            index: j as u8,
            kind: if layout::is_physical_bus(j) {
                BusKind::Physical
            } else {
                BusKind::Virtual
            },
            label: String::new(),
            gain: 0.0,
            mute: false,
            mono: 0,
            sel: false,
            eq_on: false,
            mode: BusMode::Normal,
            device: None,
        }
    }
}

/// A detail group's data (`mixer://group`). `data` is the group's own JSON (typed per group on
/// the TS side); `error` is set instead when the read failed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub struct GroupEvent {
    pub id: String,
    #[ts(type = "unknown")]
    pub data: Option<serde_json::Value>,
    pub error: Option<String>,
}

/// Meter levels, linear amplitude (1.0 = 0 dBFS). Sent over an `ipc::Channel`, ~60×/s.
/// `inputs` has 34 channels, `outputs` 64 (see `layout`). Empty while disconnected is never
/// sent; zeros are sent once on disconnect so meters fall.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub struct Levels {
    pub inputs: Vec<f32>,
    pub outputs: Vec<f32>,
}

impl Levels {
    pub fn silent() -> Self {
        Self {
            inputs: vec![0.0; layout::IN_LEVEL_CH as usize],
            outputs: vec![0.0; layout::OUT_LEVEL_CH as usize],
        }
    }
}

/// A value for `set_param`: a number (bools are 0/1) or a string (labels, device names, paths).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(untagged)]
#[ts(export, export_to = "../../src/lib/generated/")]
