/// Demo-mode simulations for UI development (FakeBackend only).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/lib/generated/")]
pub enum FakeEvent {
    /// Change a few params as if someone used Voicemeeter's own UI.
    ExternalEdit,
    /// Voicemeeter quits.
    Quit,
    /// Voicemeeter (Potato) starts.
    Start,
    /// Voicemeeter Banana starts instead (wrong edition).
    StartBanana,
    /// A USB audio device is plugged in (or unplugged, on the next call). The device list
    /// changes without a dirty flag, like a real hot-plug.
    PlugDevice,
}
